# remove_chapter 在一次删除中依次执行的三类写入：整体平移 position、
# 删除目标章节、保留章节逐章落位。跟踪回调拿到的语句文本随 Python 版本
# 可能展开参数、也可能重复出现，因此只按类别归并后核对顺序。
def classify_write(sql):
    """把跟踪到的写入语句归类为 shift/delete/landing，其余返回 None。"""
    if sql.startswith("DELETE"):
        return "delete"
    if sql.startswith("UPDATE"):
        return "shift" if "position + " in sql else "landing"
    return None

